CREATE TABLE public.crm_usage_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL, source_event_id text NOT NULL, usage_class text NOT NULL CHECK(usage_class IN('build','run')), event_type text NOT NULL, operation text NOT NULL, model text, lead_id uuid REFERENCES public.leads(id), quantity numeric CHECK(quantity>=0), quantity_unit text, credits numeric CHECK(credits>=0), cost_amount numeric CHECK(cost_amount>=0), cost_currency text, amount_basis text NOT NULL CHECK(amount_basis IN('actual','estimated','unknown')), evidence text NOT NULL, occurred_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), month_bucket text NOT NULL DEFAULT '', UNIQUE(source,source_event_id), CHECK((cost_amount IS NULL)=(cost_currency IS NULL)), CHECK(amount_basis<>'unknown' OR(credits IS NULL AND cost_amount IS NULL)));
GRANT ALL ON public.crm_usage_events TO service_role;
ALTER TABLE public.crm_usage_events ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.usage_month_bucket() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.month_bucket:=to_char(NEW.occurred_at AT TIME ZONE 'Asia/Dhaka','YYYY-MM'); RETURN NEW; END $$;
CREATE TRIGGER usage_month_bucket BEFORE INSERT ON public.crm_usage_events FOR EACH ROW EXECUTE FUNCTION public.usage_month_bucket();
CREATE INDEX crm_usage_month_lead_idx ON public.crm_usage_events(month_bucket,lead_id);
CREATE TRIGGER crm_usage_immutable BEFORE UPDATE OR DELETE ON public.crm_usage_events FOR EACH ROW EXECUTE FUNCTION public.block_history_mutation();
INSERT INTO public.crm_usage_events(source,source_event_id,usage_class,event_type,operation,model,quantity,quantity_unit,credits,amount_basis,evidence,occurred_at) SELECT 'legacy_ai_estimate',id::text,'run','ai_observation',category,model,units,'legacy_units',est_credits,'estimated','Legacy flat configured rates; not provider billing. No verifiable lead attribution.',created_at FROM public.ai_usage_events;
ALTER TABLE public.it_notices ADD COLUMN request_id uuid;
CREATE UNIQUE INDEX it_notices_request_id_idx ON public.it_notices(request_id) WHERE request_id IS NOT NULL;
CREATE TRIGGER it_notices_immutable BEFORE UPDATE OR DELETE ON public.it_notices FOR EACH ROW EXECUTE FUNCTION public.block_history_mutation();
CREATE FUNCTION public.guard_notice_receipt() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Notice deliveries are immutable'; END IF; IF NEW.notice_id IS DISTINCT FROM OLD.notice_id OR NEW.profile_id IS DISTINCT FROM OLD.profile_id OR(OLD.read_at IS NOT NULL AND NEW.read_at IS DISTINCT FROM OLD.read_at) THEN RAISE EXCEPTION 'Notice receipt is immutable after first read'; END IF; RETURN NEW; END $$;
CREATE TRIGGER notice_receipt_integrity BEFORE UPDATE OR DELETE ON public.it_notice_recipients FOR EACH ROW EXECUTE FUNCTION public.guard_notice_receipt();
CREATE FUNCTION public.publish_notice_atomic(_request uuid,_title text,_body text,_severity text,_audience text,_role text,_recipients uuid[],_author uuid,_label text,_expiry timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(_request::text,0)); SELECT id INTO n FROM public.it_notices WHERE request_id=_request; IF n IS NOT NULL THEN RETURN n; END IF; IF cardinality(_recipients)=0 OR EXISTS(SELECT 1 FROM unnest(_recipients) x WHERE NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=x AND p.is_active AND p.approval_status='approved')) THEN RAISE EXCEPTION 'Active approved recipients required'; END IF; IF _expiry IS NOT NULL AND _expiry<=now() THEN RAISE EXCEPTION 'Expiry must be in the future'; END IF; INSERT INTO public.it_notices(title,body,severity,audience_type,audience_role,author_profile_id,author_label,expires_at,request_id) VALUES(_title,_body,_severity,_audience,_role,_author,_label,_expiry,_request) RETURNING id INTO n; INSERT INTO public.it_notice_recipients(notice_id,profile_id) SELECT n,x FROM unnest(_recipients) x; INSERT INTO public.audit_logs(action,entity_type,entity_id,actor_profile_id,actor_label,metadata) VALUES('notice_published','it_notice',n,_author,_label,jsonb_build_object('recipients',cardinality(_recipients),'requestId',_request)); RETURN n; END $$;
REVOKE ALL ON FUNCTION public.publish_notice_atomic(uuid,text,text,text,text,text,uuid[],uuid,text,timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.publish_notice_atomic(uuid,text,text,text,text,text,uuid[],uuid,text,timestamptz) TO service_role;
CREATE FUNCTION public.pending_lead_age_report() RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ WITH pending AS (SELECT l.id,l.name,COALESCE(l.assigned_to,l.assigned_agent_id) agent_id,l.call_count,l.last_call_at,(SELECT max(a.created_at) FROM public.lead_assignments a WHERE a.lead_id=l.id AND a.to_agent_id=COALESCE(l.assigned_to,l.assigned_agent_id)) assigned_at FROM public.leads l WHERE l.status='pending' AND COALESCE(l.assigned_to,l.assigned_agent_id) IS NOT NULL), aged AS(SELECT p.*,q.name agent_name FROM pending p LEFT JOIN public.profiles q ON q.id=p.agent_id WHERE assigned_at<=now()-interval '48 hours') SELECT jsonb_build_object('denominator',(SELECT count(*) FROM pending),'unknownAge',(SELECT count(*) FROM pending WHERE assigned_at IS NULL),'agedCount',(SELECT count(*) FROM aged),'rows',COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM(SELECT * FROM aged ORDER BY assigned_at,id LIMIT 500) r),'[]'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.pending_lead_age_report() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pending_lead_age_report() TO service_role;